def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        raise TypeError("value cannot be None")
    try:
        lat = float(value.lat)
        lon = float(value.lon)
        time_obj = getattr(value, "time", None)
        if time_obj is None or not hasattr(time_obj, "isoformat"):
            raise TypeError("Point.time must support isoformat()")
        time_str = time_obj.isoformat()
    except Exception as e:
        raise ValueError(f"Invalid Point object: {e}") from e
    return {"lat": lat, "lon": lon, "time": time_str}

