def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Ensure a valid protocol_version type if provided
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError(f"protocol_version must be a tuple, got {type(protocol_version).__name__}")

    handlers = {}
    # Scan class attributes for potential handler classes.
    for attr_name, attr_value in vars(cls).items():
        # Candidate handler must be a class
        if not isinstance(attr_value, type):
            continue
        # Look for known attributes that encode the protocol version.
        # Common conventions are : PROTOCOL_INFO, PROTOCOL_VERSION, or protocol_version.
        version = getattr(attr_value, 'PROTOCOL_INFO', None)
        if version is None:
            version = getattr(attr_value, 'PROTOCOL_VERSION', None)
        if version is None:
            version = getattr(attr_value, 'protocol_version', None)
        if not version:
            continue
        # Normalise to a tuple of two integers.
        try:
            if isinstance(version, (list, tuple)) and len(version) == 2:
                version_tuple = (int(version[0]), int(version[1]))
            else:
                # Try to parse from a string like "3.5" or "3,5"
                if isinstance(version, str):
                    parts = version.replace(',', '.').split('.')
                    if len(parts) == 2:
                        version_tuple = (int(parts[0]), int(parts[1]))
                    else:
                        raise ValueError
                else:
                    # Unsupported format; skip this handler.
                    continue
        except (ValueError, TypeError):
            # If we can't interpret the version, skip.
            continue

        handlers[version_tuple] = attr_value

    if protocol_version is None:
        return handlers

    # Return only the requested version if it exists.
    return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

