def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no specific keys are supplied, just return all values.
    if not keys:
        try:
            return list(self.values())
        except AttributeError:
            # Fallback for sequence types
            return list(self)

    # Otherwise collect the requested values.
    results = []
    for key in keys:
        try:
            results.append(self[key])
        except (KeyError, TypeError):
            # The key might refer to an integer index for a sequence-like
            # object.  Try that as a fallback.
            if isinstance(key, int) and hasattr(self, "__len__") and hasattr(self, "__getitem__"):
                if 0 <= key < len(self):
                    results.append(self[key])
                else:
                    raise KeyError(f"Index {key} is out of range for the record.")
            else:
                raise KeyError(f"Key {key!r} not found in the record.")

    return results

