def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """
    Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    # Basic validation
    if not isinstance(cmd, (tuple, list)):
        raise TypeError(f'cmd must be a tuple or list of strings, got {type(cmd)}')
    if len(cmd) == 0:
        return tuple()

    new_cmd = list(cmd)

    try:
        import os
        import sys
        import platform
        import shutil

        # Only on Windows we perform shebang resolution.
        if platform.system() == 'Windows':
            script_path = cmd[0]
            # If the first arg is a path that points to a file, try to read shebang.
            if os.path.isfile(script_path):
                try:
                    with open(script_path, 'rb') as f:
                        first_line = f.readline().decode(errors='ignore')
                    if first_line.startswith('#!'):
                        # Extract interpreter from shebang.
                        shebang = first_line[2:].strip()
                        # Handle env wrapper.
                        if shebang.startswith('env '):
                            parts = shebang.split()
                            if len(parts) >= 2:
                                interpreter = parts[1]
                            else:
                                interpreter = 'python.exe'
                        else:
                            interpreter = shebang.split()[0]

                        # Resolve actual interpreter path if possible.
                        interp_path = shutil.which(interpreter)
                        if interp_path is None:
                            # Fall back to current python executable.
                            interp_path = sys.executable

                        # Reconstruct the command: [interpreter, script] + original args after script.
                        new_cmd = [interp_path, script_path] + list(cmd[1:])
                except Exception:
                    # If anything goes wrong, silently ignore and keep original command.
                    pass
    except Exception:
        # If imports fail or some other issue, simply return the original tuple.
        pass

    return tuple(new_cmd)

