def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        if cache is None:
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            @wraps(func)
            def wrapper(*args, **kwargs):
                try:
                    k = key(*args, **kwargs)
                except Exception:
                    # If key function fails, fall back to no caching
                    return func(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass
                value = func(*args, **kwargs)
                try:
                    cache[k] = value
                except Exception:
                    # ignore cache errors (e.g., value too large)
                    pass
                return value
        else:
            @wraps(func)
            def wrapper(*args, **kwargs):
