def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.

    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    import traceback
    import os

    def _shorten_path(path, limit):
        """Return a path with only the last `limit` components, prefixed by '...' if truncated."""
        try:
            norm = os.path.normpath(path)
        except Exception:
            norm = path
        parts = norm.split(os.sep)
        if len(parts) > limit and limit > 0:
            return os.sep.join(['...'] + parts[-limit:])
        return norm

    # Basic safety: ensure e is a BaseException
    if not isinstance(e, BaseException):
        try:
            return str(e)
        except Exception:
            return repr(e)

    # Build message parts
    parts = [f"Exception raised: {e.__class__.__name__}: {e}"]

    # Gather traceback entries
    tb = e.__traceback__
    if tb is not None:
        # Use extract_tb to get a list of FrameSummary objects
        extracted = traceback.extract_tb(tb)
        if max_level is None or max_level <= 0:
            sliced = extracted
        else:
            sliced = extracted[:max_level]
        for idx, frame in enumerate(sliced, 1):
            file_path = _shorten_path(frame.filename, max_path_level)
            parts.append(f"  [{idx}] File \"{file_path}\", line {frame.lineno}, in {frame.name}")

        # Handle nested causes or contexts if available
        for depth, (name, nested) in enumerate(
            [("cause", e.__cause__), ("context", e.__context__)], start=1
        ):
            if nested:
                parts.append(f"\n{depth}. {name.capitalize()}:")
                try:
                    # Recursively format the nested exception, but limit stack depth to 0 to avoid too verbose output
                    nested_str = cls.extostr(nested, max_level=0, max_path_level=max_path_level)
                except Exception:
                    nested_str = f"  <Unable to format nested {name}>"
                parts.append(nested_str)
    else:
        parts.append("  No traceback available.")

    return "\n".join(parts)

