def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    lines = []

    # Add optional header
    if header is not None:
        lines.append(str(header))

    # Helper to check if an object is an iterable of scalar values
    def is_scalar_iter(obj):
        return isinstance(obj, (list, tuple, set, frozenset)) and not isinstance(obj, str)

    try:
        for point in self:
            # Expect each point to be a pair (coord, value)
            try:
                coord, value = point
            except Exception:
                # If point is not a pair, skip it with a warning
                continue

            items = []

            # Handle coordinate
            if is_scalar_iter(coord):
                items.extend(map(str, coord))
            else:
                items.append(str(coord))

            # Handle value
            if is_scalar_iter(value):
                items.extend(map(str, value))
            else:
                # Treat value as a single scalar
                items.append(str(value))

            # Join items using the requested separator
            lines.append(separator.join(items))

    except TypeError:
        raise TypeError("Object is not iterable, cannot convert to CSV")

    # Return the CSV string (each line separated by a newline)
    return "\n".join(lines)

