def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        # Convert coordinates to ndarray
        coord = np.asarray(coord)
    except Exception:
        raise TypeError("coord must be array-like")
    # Determine histogram dimensionality
    edges = getattr(self, "edges", None)
    if edges is None:
        raise AttributeError("Histogram edges not found on instance")
    ndim = len(edges)
    # Standardize coordinate shape
    if coord.ndim == 1:
        if coord.shape[0] != ndim:
            raise ValueError(f"coord of shape {coord.shape} does not match histogram dimensionality {ndim}")
        points = coord.reshape((1, ndim))
    elif coord.ndim == 2:
        if coord.shape[1] != ndim:
            raise ValueError(f"Second dimension of coord must be {ndim}")
        points = coord
    else:
        raise ValueError("coord must be 1-D or 2-D array")
    # Ensure weight matches number of points
    if np.isscalar(weight):
        weights = np.full(points.shape[0], weight, dtype=type(weight))
    else:
        try:
            weight = np.asarray(weight)
        except Exception:
            raise TypeError("weight must be array-like or scalar")
        if weight.ndim == 0:
            weights = np.full(points.shape[0], weight, dtype=weight.dtype)
        elif weight.ndim == 1 and weight.shape[0] == points.shape[0]:
            weights = weight
        else:
            raise ValueError("weight must be scalar or 1-D array of length equal to number of points")
    # Get histogram data
    data = getattr(self, "data", None)
    if data is None:
        raise AttributeError("Histogram data not found on instance")
    # Compute bin indices for each point
    indices = []
    for dim in range(ndim):
        edge = edges[dim]
        # Use searchsorted to find rightmost index such that edge[i] <= coord < edge[i+1]
        idx = np.searchsorted(edge, points[:, dim], side="right") - 1
        indices.append(idx)
    indices = np.column_stack(indices)
    # Determine which points fall within valid bin ranges
    max_index = np.array(data.shape)
    valid = np.all((indices >= 0) & (indices < max_index), axis=1)
    if not np.any(valid):
        # All points outside; nothing to do
        return
    # Increment histogram counts with corresponding weights
    for ind, w in zip(indices[valid], weights[valid]):
        try:
            data[tuple(ind)] += w
        except Exception as exc:
            raise IndexError(f"Failed to update histogram at index {tuple(ind)}: {exc}")
    # Store updated data back
    self.data = data
    return

