def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    errors = []

    # Assume KEY_REGEX and VALUE_REGEX are compiled regular expressions defined elsewhere
    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            key_rep = repr(key)
            errors.append({key_rep: 'expected string or bytes-like object'})
        else:
            try:
                if not KEY_REGEX.match(key):
                    errors.append({key: f"Label key '{key}' does not match the regex [...]"})
            except Exception:
                # If the regex is not defined or used incorrectly, append a generic error
                errors.append({key: f"Failed to validate key '{key}' against regex"})

        # Validate value type
        if not isinstance(value, (str, bytes)):
            val_rep = repr(value)
            errors.append({val_rep: 'expected string or bytes-like object'})
        else:
            try:
                if not VALUE_REGEX.match(value):
                    errors.append({repr(value): f"Label value '{value}' does not match the regex [...]"})
            except Exception:
                errors.append({repr(value): f"Failed to validate value '{value}' against regex"})

    if errors:
        raise ValidationError(errors)

