            # If the log is a single string, treat each line separately
            items = log.splitlines()
        else:
            items = list(log)
    except Exception:
        # If iteration fails, treat the whole log as a single message
        items = [log]
    # If there are no items, return an empty string
    if not items:
        return ''
    # Convert each item to string and prepend prefix if provided
    lines = [str(item) for item in items]
    if prefix:
        lines = [f"{prefix}{line}" for line in lines]
    # Join the lines with newline characters
    return "\n".join(lines)

