    """Check all digests in manifest that are needed are present and used."""
    if manifest_files is None:
        raise ValueError("manifest_files cannot be None")
    if digests_used is None:
        raise ValueError("digests_used cannot be None")

    # Ensure digests_used is a set for quick lookup
    used_set = set(digests_used)

    missing = set()
    for filename, required in manifest_files.items():
        # `required` may be a single digest or an iterable of digests
        if required is None:
            continue
        if isinstance(required, (str, bytes)):
            required = [required]
        for digest in required:
            if digest not in used_set:
                missing.add(digest)

    if missing:
        missing_list = ', '.join(sorted(missing))
        raise ValueError(f"Required digests not used: {missing_list}")

