def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Basic type check
        if prior is None:
            raise ValueError("Prior cannot be None.")
        if not isinstance(prior, type(self)):
            raise ValueError(
                f"Prior must be an instance of {type(self).__name__}, "
                f"got {type(prior).__name__}."
            )

        # Ensure both inventories belong to the same model (if a model_id attribute exists)
        model_id_self = getattr(self, "model_id", None)
        model_id_prior = getattr(prior, "model_id", None)
        if model_id_self is not None and model_id_prior is not None:
            if model_id_self != model_id_prior:
                raise ValueError(
                    f"Model ID mismatch: self has {model_id_self}, "
                    f"prior has {model_id_prior}."
                )

        # Compare inventory versions
        ver_self = getattr(self, "inventory_version", None)
        ver_prior = getattr(prior, "inventory_version", None)
        if ver_self is None or ver_prior is None:
            raise ValueError(
                "Both inventories must define an 'inventory_version' attribute "
                "to compare versions."
            )

        if ver_prior >= ver_self:
            raise ValueError(
                f"Prior inventory version ({ver_prior}) must be "
                f"older than the current inventory version ({ver_self})."
            )

        # Optional: if current inventory keeps a history of versions, check inclusion
        history_self = getattr(self, "version_history", None)
        if history_self is not None:
            if ver_prior not in history_self:
                raise ValueError(
                    f"Prior inventory version ({ver_prior}) is not found "
                    f"in the current inventory's version history."
                )

        # All checks passed; nothing to return
        return

