def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a mapping of versions to data")
    if version not in inventory:
        raise KeyError(f"Version '{version}' not found in inventory")
    # Base mapping from the requested version
    base_data = inventory[version]
    if not isinstance(base_data, dict):
        raise TypeError("Inventory[version] must be a mapping of logical paths to files")
    result = {}
    for logical_path, files in base_data.items():
        # Ensure we have a set of files
        try:
            result[logical_path] = set(files)
        except TypeError:
            # If files is a single non-iterable item
            result[logical_path] = {files}
    # Include duplicate file references from other versions
    for ver_key, data in inventory.items():
        if ver_key == version:
            continue
        if not isinstance(data, dict):
            continue
        for logical_path in result:
            if logical_path in data:
                files = data[logical_path]
                if isinstance(files, (set, list, tuple)):
                    result[logical_path].update(files)
                else:
                    result[logical_path].add(files)
    return result

