def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(manifest_files, (set, list)):
        raise ValueError("manifest_files must be a set or list of file paths")

    manifest_set = set(manifest_files)

    if isinstance(fixity, dict):
        # Accept a mapping of file -> checksum
        for file_path, hash_value in fixity.items():
            if file_path not in manifest_set:
                raise ValueError(f"Fixity refers to unknown file: {file_path}")
            if not isinstance(hash_value, str):
                raise ValueError(f"Hash for {file_path} must be a string")
    elif isinstance(fixity, list):
        # Accept a list of dicts describing each file
        for idx, entry in enumerate(fixity):
            if not isinstance(entry, dict):
                raise ValueError(f"Fixity entry at index {idx} must be a dict")
            if "file" not in entry:
                raise ValueError(f"Fixity entry at index {idx} missing required 'file' key")
            file_path = entry["file"]
            if file_path not in manifest_set:
                raise ValueError(f"Fixity refers to unknown file: {file_path}")
            # Ensure that an actual checksum/hash is present
            if not any(k in entry for k in ("hash", "checksum", "md5", "sha256", "sha1")):
                raise ValueError(f"Fixity entry for '{file_path}' missing checksum key")
    else:
        raise ValueError("Fixity block must be either a dict or a list")
    # If all checks pass, nothing is returned (validation successful)

