def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
        A dictionary where each key is the basename of an XML file
        (without extension) and the value is a sorted list of absolute
        paths of all files that belong to that package (including the
        XML file itself).
    """
    import os
    from collections import defaultdict

    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Provided path '{folder}' is not a directory")

    # Find all XML files and record their basenames
    xml_basenames = set()
    for root, _, files in os.walk(folder):
        for filename in files:
            if filename.lower().endswith(".xml"):
                xml_basenames.add(os.path.splitext(filename)[0])

    if not xml_basenames:
        return {}

    # Group files by the basename of the XML file.
    packages = defaultdict(set)
    for root, _, files in os.walk(folder):
        for filename in files:
            # Determine which package this file belongs to
            for base in xml_basenames:
                # Match the XML basename or any file that starts with it
                if filename == f"{base}.xml" or filename.startswith(f"{base}."):
                    packages[base].add(os.path.join(root, filename))
                    break  # A file belongs to at most one package in this logic

    # Convert sets to sorted lists and return as a regular dict
    return {base: sorted(list(files)) for base, files in packages.items()}

