def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # -------------------------------------------------------------------
    # Validate pieces
    # -------------------------------------------------------------------
    if not isinstance(pieces, (list, tuple, dict)):
        raise TypeError("`pieces` must be a list, tuple, or dict")
    if isinstance(pieces, dict):
        # Expected keys for a semantic version
        parts = [
            pieces.get("major"),
            pieces.get("minor"),
            pieces.get("patch"),
            pieces.get("prerelease"),
            pieces.get("build")
        ]
    else:
        parts = list(pieces)
    # Ensure we have at least three components (major, minor, patch)
    if len(parts) < 3:
        raise ValueError("`pieces` must contain at least major, minor, and patch")

    # Convert non‑None parts to strings
    string_parts = [str(p) if p is not None else None for p in parts]

    # -------------------------------------------------------------------
    # Style dispatch
    # -------------------------------------------------------------------
    def _semantic(parts):
        major, minor, patch, prerelease, build = parts[:5]
        if major is None or minor is None or patch is None:
            raise ValueError("semantic style requires major, minor, and patch")
        base = f"{major}.{minor}.{patch}"
        if prerelease:
            base += f"-{prerelease}"
        if build:
            base += f"+{build}"
        return base

    def _full(parts):
        major, minor, patch = parts[:3]
        if major is None or minor is None or patch is None:
            raise ValueError("full style requires major, minor, and patch")
        return f"{major}.{minor}.{patch}"

    def _short(parts):
        major, minor = parts[:2]
        if major is None or minor is None:
            raise ValueError("short style requires major and minor")
        return f"{major}.{minor}"

    style_map = {
        "semantic": _semantic,
        "full": _full,
        "short": _short,
    }

    if not isinstance(style, str):
        raise TypeError("`style` must be a string")
    formatter = style_map.get(style.lower())
    if formatter is None:
        raise ValueError(
            f"Unsupported style '{style}'. Supported styles: {list(style_map.keys())}"
        )
    return formatter(string_parts)

