def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        cmd_base = [commands]
    else:
        try:
            cmd_base = list(commands)
            if not all(isinstance(x, str) for x in cmd_base):
                raise ValueError
        except Exception:
            raise TypeError("commands must be a string or iterable of strings")

    if isinstance(args, str):
        args_list = [args]
    else:
        try:
            args_list = list(args)
            if not all(isinstance(x, str) for x in args_list):
                raise ValueError
        except Exception:
            raise TypeError("args must be a string or iterable of strings")

    full_cmd = cmd_base + args_list

    if not full_cmd:
        raise ValueError("No command provided to run")

    if verbose:
        print("Running command:", ' '.join(full_cmd))

    # Prepare stdout and stderr handling
    # Capture stdout if verbose to display output, otherwise discard
    stdout_cfg = subprocess.PIPE if verbose else subprocess.DEVNULL
    stderr_cfg = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        completed = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=stdout_cfg,
            stderr=stderr_cfg,
            check=True,
            text=True
        )
    except subprocess.CalledProcessError as exc:
        # Build a helpful error message
        err_msg = (
            f"Command '{' '.join(full_cmd)}' exited with non-zero status {exc.returncode}"
        )
        if not hide_stderr and exc.stderr:
            err_msg += f"\nstderr: {exc.stderr}"
        # Re-raise as RuntimeError for caller
        raise RuntimeError(err_msg) from exc

    # If verbose, print captured stdout
    if verbose and completed.stdout:
        print(completed.stdout.rstrip())

    return completed

