def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return ""
    v = version.strip()
    parts = v.split('.')
    if len(parts) != 3:
        return v

    new_parts = []
    for part in parts:
        # Preserve original padding
        padded = part.startswith('0') and len(part) > 1
        try:
            num = int(part)
        except ValueError:
            # Non-numeric part; return original
            return v
        num += 1
        new_part = str(num)
        if padded:
            new_part = new_part.zfill(len(part))
        new_parts.append(new_part)

    return ".".join(new_parts)

