def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be an iterable list or tuple of directory names")

    # Ensure we have a root inventory to compare against
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise AttributeError("Object must have a 'root_inventory' dictionary attribute")

    # Optional: store differences in a dict on the instance
    self._differential_digests = {}

    # Iterate over the supplied version directories in order
    for ver_dir in version_dirs:
        if not isinstance(ver_dir, str):
            raise TypeError(f"Version directory name must be a string, got {type(ver_dir).__name__}")

        # Construct the expected inventory path (assumes a file called 'inventory.json')
        inv_path = os.path.join(self.base_dir, ver_dir, "inventory.json")

        if not os.path.isfile(inv_path):
            raise ValueError(f"Missing inventory for version '{ver_dir}' at '{inv_path}'")

        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inv_data = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Error reading inventory for version '{ver_dir}': {exc}")

        digests = inv_data.get("digests")
        if not isinstance(digests, dict):
            raise ValueError(
                f"Inventory for version '{ver_dir}' must contain a 'digests' dictionary"
            )

        # Compare each digest against the root inventory, recording differences
        root_digests = self.root_inventory.get("digests", {})
        diff = {k: v for k, v in digests.items() if root_digests.get(k) != v}
        self._differential_digests[ver_dir] = diff

    return self

