    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for idx, d in enumerate(dicts):
        if not isinstance(d, dict):
            raise TypeError(f"Element at index {idx} is not a dict: {type(d).__name__}")
        for key, value in d.items():
            if isinstance(value, (int, float)):
                result[key] = result.get(key, 0) + value
            else:
                raise TypeError(
                    f"Non-numeric value for key '{key}': {value!r} (type {type(value).__name__})"
                )
    return result

