def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an integer, got {type(number).__name__}")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two symbols to represent a numeral system")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding cannot be negative")

    base = len(alphabet)
    sign = '' if number >= 0 else '-'
    n = abs(number)

    # Special case for zero
    if n == 0:
        result = alphabet[0]
    else:
        digits = []
        while n > 0:
            digit = n % base
            digits.append(alphabet[digit])
            n //= base
        result = ''.join(reversed(digits))

    # Apply padding with the first symbol of the alphabet
    if padding is not None:
        pad_len = padding - len(result)
        if pad_len > 0:
            result = alphabet[0] * pad_len + result

    return sign + result

