def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("Expected a class as argument, got %r" % (cls,))
    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        try:
            subs = current.__subclasses__()
        except Exception:
            continue
        for sub in subs:
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    return seen

