def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise TypeError("string must be a str")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple of unique symbols")
    base = len(alphabet)
    if base == 0:
        raise ValueError("alphabet must contain at least one symbol")
    # Ensure all alphabet entries are single-character strings
    for sym in alphabet:
        if not isinstance(sym, str) or len(sym) != 1:
            raise ValueError(f"alphabet entries must be single-character strings, found {sym!r}")
    # Check for duplicates
    if len(set(alphabet)) != base:
        raise ValueError("alphabet contains duplicate symbols")
    # Build reverse lookup
    lookup = {sym: i for i, sym in enumerate(alphabet)}
    result = 0
    for pos, char in enumerate(string):
        if char not in lookup:
            raise ValueError(f"character {char!r} at position {pos} is not in alphabet")
        result = result * base + lookup[char]
    return result

