def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Remove matching leading and trailing quotes if present
    if len(name) >= 2 and name[0] in ('"', "'") and name[-1] == name[0]:
        unquoted = name[1:-1]
    else:
        unquoted = name
        if unquoted and unquoted[0] in ('"', "'"):
            unquoted = unquoted[1:]
        if unquoted and unquoted[-1] in ('"', "'"):
            unquoted = unquoted[:-1]
    # Replace common escaped quote sequences
    unquoted = unquoted.replace('\\"', '"').replace("\\'", "'")
    return unquoted

