def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Validate input type
    if not isinstance(s, (bytes, bytearray)):
        raise TypeError("s must be a bytes-like object")
    # Ensure we have a string for splitting
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode('utf-8')
        except Exception:
            raise ValueError("Failed to decode s as UTF-8")
    # Resolve platform
    if platform == 'this':
        import sys
        platform = 0 if sys.platform.startswith('win') else 1
    if platform not in (0, 1):
        raise ValueError(f"Unsupported platform value: {platform}")
    # POSIX: use shlex
    if platform == 1:
        import shlex
        try:
            return shlex.split(s)
        except Exception as exc:
            raise RuntimeError(f"shlex.split failed: {exc}") from exc
    # Windows variant
    args = []
    current = []
    in_quote = None
    escape = False
    for ch in s:
        if escape:
            current.append(ch)
            escape = False
        elif ch == '\\':
            escape = True
        elif ch in ('"', "'"):
            if not in_quote:
                in_quote = ch
            elif in_quote == ch:
                in_quote = None
            else:
                current.append(ch)
        elif ch.isspace():
            if in_quote:
                current.append(ch)
            elif current:
                args.append(''.join(current))
                current = []
        else:
            current.append(ch)
    if current:
        args.append(''.join(current))
    return args

