def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    host_str = str(host).strip()
    if host_str.lower() == 'localhost':
        return True

    try:
        for info in socket.getaddrinfo(host_str, None):
            sockaddr = info[4]
            ip = sockaddr[0]
            # IPv6 addresses contain ':'
            if ':' in ip:
                try:
                    addr_bytes = socket.inet_pton(socket.AF_INET6, ip)
                except OSError:
                    continue
                if addr_bytes == b'\x00' * 15 + b'\x01':
                    return True
            else:
                try:
                    packed = socket.inet_aton(ip)
                except OSError:
                    continue
                if packed[0] == 127:
                    return True
    except socket.gaierror:
        return False

    return False

