def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:
        ['foo.txt', 'pp:root/somedir']
    ... transform that into:
        ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    import re

    # Normalise input to an iterable of strings
    if isinstance(find_paths, str):
        fragments = [find_paths]
    else:
        try:
            fragments = list(find_paths)
        except TypeError:
            raise TypeError(
                f"find_paths must be a string or an iterable, got {type(find_paths)!r}"
            )

    transformed = []
    # Any string containing a colon is considered a pre‑existing pattern (e.g., 'pp:…')
    pattern_start = re.compile(r'^[^:]+:')

    # Escape glob meta‑characters for fragments to avoid accidental globbing
    def escape(pattern: str) -> str:
        return re.sub(r'([?\*\[])', r'[\1]', pattern)

    for fragment in fragments:
        if not isinstance(fragment, str):
            fragment = str(fragment)
        if pattern_start.match(fragment):
            # Preserve user supplied pattern unchanged
            transformed.append(fragment)
        else:
            # Build a shell‑style recursive glob that matches any file or directory
            # whose name contains the fragment somewhere.
            escaped = escape(fragment)
            transformed.append(f"sh:**/*{escaped}*/**")
    return transformed

