def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern.
    If the input is already a compiled pattern object it is returned unchanged.
    A None input will return None. If an invalid type is supplied a
    TypeError will be raised.
    """
    # Return None unchanged
    if pattern is None:
        return None

    # Determine the type used by the re module for compiled patterns
    try:
        compiled_pattern_type = re.Pattern
    except AttributeError:
        compiled_pattern_type = type(re.compile(""))

    # If already a compiled pattern, return it
    if isinstance(pattern, compiled_pattern_type):
        return pattern

    # If a string, strip whitespace optionally and compile
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)

    # Anything else is not acceptable
    raise TypeError("Invalid pattern type: %r" % (type(pattern),))

