def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if commands is None:
        raise ValueError("No commands provided")
    # Normalize commands to a list
    if isinstance(commands, str):
        commands = [commands]
    elif hasattr(commands, '__iter__'):
        commands = list(commands)
    else:
        raise TypeError("commands must be a string or iterable of strings")
    # Normalize args to a list
    if args is None:
        args = []
    elif isinstance(args, str):
        args = [args]
    elif hasattr(args, '__iter__'):
        args = list(args)
    else:
        raise TypeError("args must be a string, list of strings, or None")
    output = None
    for cmd in commands:
        if verbose:
            full_cmd_str = cmd if isinstance(cmd, str) else " ".join(cmd)
            if args:
                full_cmd_str += " " + " ".join(map(str, args))
            print(f"Running command: {full_cmd_str}")
        try:
            if isinstance(cmd, str):
                # Build full command string with args
                full_cmd = cmd
                if args:
                    full_cmd += " " + " ".join(map(str, args))
                result = subprocess.run(
                    full_cmd,
                    cwd=cwd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
                    env=env,
                    text=True,
                    shell=True
                )
            else:
                # cmd is a sequence; extend with args
                full_cmd = list(cmd)
                if args:
                    full_cmd.extend(args)
                result = subprocess.run(
                    full_cmd,
                    cwd=cwd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
                    env=env,
                    text=True,
                    shell=False
                )
            if result.returncode != 0:
                raise RuntimeError(
                    f"Command '{cmd}' failed with exit code {result.returncode}"
                    f"\nstdout: {result.stdout}"
                    f"\nstderr: {result.stderr}"
                )
            output = result.stdout
        except FileNotFoundError as e:
            raise RuntimeError(f"Command not found: {cmd}") from e
        except Exception as e:
            raise RuntimeError(f"Error executing command '{cmd}': {e}") from e
    return output

