def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper:
        dump_func = yaml.dump
        kwargs = {"dumper": dumper}
    else:
        dump_func = yaml.safe_dump
        kwargs = {}
    # Perform the dump
    data = dump_func(obj, **kwargs)
    # Ensure the result is a unicode string (Python 3 str) or Python 2 u'...' string
    if isinstance(data, bytes):
        try:
            return data.decode("utf-8")
        except Exception:
            # fallback: replace undecodable bytes
            return data.decode("utf-8", errors="replace")
    # If data is None (some dumper could return None), return an empty string
    return data if data is not None else ""

