def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate and normalize shape
    try:
        if isinstance(shape, int):
            shape = (shape,)
        shape_tuple = tuple(shape)
    except Exception as exc:
        raise ValueError("shape must be an integer or tuple of integers") from exc

    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError("dtype could not be converted to numpy dtype") from exc

    # Ensure dimensions are non-negative
    if any(s < 0 for s in shape_tuple):
        raise ValueError("shape dimensions must be non-negative")

    # Create and return the array
    try:
        return np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape_tuple} and dtype {dtype_obj}") from exc

