def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    from configparser import ConfigParser
    import logging

    # Ensure yaml and toml are available if used
    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None

    configs = {}
    log_records = []

    # Helper to resolve environment variables recursively
    def _resolve_env_recursive(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _resolve_env_recursive(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_resolve_env_recursive(v) for v in value]
        return value

    # Helper to create a LogRecord for errors
    def _make_error_record(message, exc_info=None):
        logger_name = 'load_configurations'
        record = logging.LogRecord(
            name=logger_name,
            level=logging.ERROR,
            pathname=__file__,
            lineno=0,
            msg=message,
            args=(),
            exc_info=exc_info
        )
        return record

    for filename in config_filenames:
        if not os.path.isfile(filename):
            log_records.append(_make_error_record(f"File does not exist: {filename}"))
            continue

        ext = os.path.splitext(filename)[1].lower()
        try:
            if ext in ('.ini', '.cfg'):
                parser = ConfigParser()
                parser.read(filename)
                # Convert to dict
                parsed = {section: dict(parser.items(section)) for section in parser.sections()}
            elif ext == '.json':
                with open(filename, 'r', encoding='utf-8') as f:
                    parsed = json.load(f)
            elif ext in ('.yaml', '.yml') and yaml is not None:
                with open(filename, 'r', encoding='utf-8') as f:
                    parsed = yaml.safe_load(f)
            elif ext == '.toml' and toml is not None:
                with open(filename, 'r', encoding='utf-8') as f:
                    parsed = toml.loads(f.read())
            else:
                # Unsupported extension
                log_records.append(_make_error_record(f"Unsupported configuration file type: {filename}"))
                continue

            if resolve_env:
                parsed = _resolve_env_recursive(parsed)

            # Apply overrides if any
            if overrides:
                def apply_override(base, overrides_dict):
                    for k, v in overrides_dict.items():
                        if isinstance(v, dict) and isinstance(base.get(k), dict):
                            apply_override(base[k], v)
                        else:
                            base[k] = v
                apply_override(parsed, overrides)

            configs[filename] = parsed

        except Exception as exc:
            # Capture exception info in log record
            log_records.append(_make_error_record(f"Error parsing {filename}", exc_info=(type(exc), exc, exc.__traceback__)))

    return configs, log_records

