def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is a sequence type (list, tuple, set, frozenset) but not str or bytes
    seq_types = (list, tuple, set, frozenset)
    try:
        if isinstance(seq, seq_types):
            return (seq, type(seq).__name__)
        # Treat str and bytes as sequence data
        if isinstance(seq, (str, bytes)):
            return (seq, 'seq')
        # File‑like object with a read() method
        read = getattr(seq, "read", None)
        if callable(read):
            try:
                data = seq.read(bufsize) if bufsize is not None else seq.read()
                if isinstance(data, (str, bytes)):
                    return (data, "file")
            except Exception:
                pass
        # Any other iterable – consume it into a list
        iterable = iter(seq)  # will raise TypeError if not iterable
        seq_list = list(iterable)
        return (seq_list, "iterable")
    except Exception as e:
        # Reraise as ValueError with context
        raise ValueError(f"Unsupported seq type: {type(seq)}") from e

