def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Determine if candidate is a class or instance
    if isinstance(candidate, type):
        cand_cls = candidate
        is_cls = True
    else:
        cand_cls = type(candidate)
        is_cls = False

    # Quick check: subclass relationship for classes
    try:
        if is_cls and issubclass(cand_cls, iface):
            return True
    except TypeError:
        # Either iface or cand_cls is not a class; ignore
        pass

    # Gather required attributes from the interface definition
    missing = []
    for name, iface_attr in iface.__dict__.items():
        # Skip special attributes
        if name.startswith('__'):
            continue

        # Does the candidate provide this attribute?
        if not hasattr(candidate, name):
            missing.append(name)
            continue

        cand_attr = getattr(candidate, name)

        # If the interface attribute is callable, expect the candidate to provide a callable
        if callable(iface_attr) and not callable(cand_attr):
            missing.append(name)

    if missing:
        msg = (
            "Candidate {} does not provide the required attributes/methods "
            "found in interface {}: {}"
