def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass was provided, use it
    if explicit_mc is not None:
        return explicit_mc

    # If no bases were supplied, the default metaclass is 'type'
    if not bases:
        return type

    # Gather the metaclasses of all bases
    try:
        metaclasses = [type(b) for b in bases]
    except Exception as exc:
        raise TypeError("All bases must be classes") from exc

    # Find the most derived metaclass among all base metaclasses
    most_derived = metaclasses[0]
    for candidate in metaclasses[1:]:
        if issubclass(candidate, most_derived):
            most_derived = candidate
        elif not issubclass(most_derived, candidate):
