def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Try public payload (JSON)
    try:
        payload = json.loads(decode_if_bytes(request.body))
        if payload.get("diaspora_public") is not None:
            return True
    except Exception:
        pass

    # Try private payload (JSON, must contain an encrypted envelope)
    try:
        payload = json.loads(decode_if_bytes(request.body))
        if payload.get("diaspora_private") is not None and payload.get("encrypted_magic_envelope") is not None:
            return True
    except Exception:
        pass

    # Try legacy payload (XML)
    try:
        xml_tree = etree.fromstring(encode_if_text(request.body))
        if xml_tree.tag == "diaspora:legacy" or xml_tree.tag == "{http://example.org/diaspora}legacy":
            return True
    except Exception:
        pass

    return False

