def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    import datetime
    if not isinstance(dt, datetime.datetime):
        raise TypeError("Expected datetime.datetime instance, got %s" % type(dt).__name__)
    # Ensure we have a UTC-aware datetime
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        dt = dt.astimezone(datetime.timezone.utc)
    # Format without microseconds (matching typical ISO representation used by D* nodes)
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

