def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # A valid tag must be a non-empty string containing only
    # alphanumeric characters, underscore, or hyphen, and its length
    # should be between 1 and 64 characters.
    try:
        if not isinstance(tag, str):
            return False
        tag = tag.strip()
        if not tag:
            return False
        if len(tag) > 64:
            return False
        import re
        pattern = r'^[A-Za-z0-9_-]+$'
        return re.match(pattern, tag) is not None
    except Exception:
        # Any unexpected error should result in False, not a crash
        return False

