def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    # Try to get the children. ElementTree elements support iteration
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError(f"Expected an XML element with children, got {type(node)!r}") from exc

    result = {}
    for child in children:
        tag = getattr(child, 'tag', None)
        if tag is None:
            continue
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

