def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url or not isinstance(url, str):
        raise ValueError("url must be a non-empty string")
    # Default path for the nodeinfo document if none provided
    default_path = "nodeinfo"
    try:
        path = document_path if document_path is not None else default_path
        # Ensure path does not start with a slash for consistent concatenation
        path = path.lstrip("/")
        # Build the href by concatenating the base url and path
        href = url.rstrip("/") + "/" + path
        # The NodeInfo spec requires this rel
        rel = "http://nodeinfo.diaspora.software/ns/schema/1.0"
        return {
            "links": [
                {"rel": rel, "href": href}
            ]
        }
    except Exception as exc:
        raise RuntimeError(f"Unable to generate nodeinfo document for {url}: {exc}") from exc

