def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    The function scans one or more directories provided in ``settings_dirs`` and
    returns a sorted list of fully‑qualified file paths that match the
    ``spec_option`` filter. ``spec_option`` may be:
    - ``None`` or an empty string: all files are returned.
    - a string such as ``'.ini'`` to match file extensions.
    - a list or tuple of strings: a file is included if it ends with any of
      the strings.
    - a compiled regular expression: a file is included if the pattern
      matches the file name.

    Parameters
    ----------
    settings_dirs : str or Iterable[str]
        Directory or list of directories to search. Non‑existent directories
        are ignored.
    spec_option : str, Iterable[str] or re.Pattern, optional
        Pattern used to filter file names; see the description above.

    Returns
    -------
    list[str]
        Sorted list of fully‑qualified file paths that satisfy the filter.
    """
    import os
    import re

    # Normalise settings_dirs to a list
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            # If it's not iterable, treat it as a single directory
            dirs = [settings_dirs]

    # Normalise spec_option
    if spec_option is None or spec_option == "":
        matcher = lambda _: True
    elif isinstance(spec_option, (list, tuple)):
        suffixes = [s for s in spec_option if isinstance(s, str)]
        matcher = lambda f: any(f.endswith(suffix) for suffix in suffixes)
    elif hasattr(spec_option, "search") and callable(spec_option.search):
        matcher = lambda f: bool(spec_option.search(f))
    elif isinstance(spec_option, str):
        matcher = lambda f: f.endswith(spec_option)
    else:
        raise TypeError(
            f"Unsupported spec_option type: {type(spec_option).__name__}"
        )

    result = []
    for d in dirs:
        try:
            if not os.path.isdir(d):
                continue
            for entry in os.listdir(d):
                if matcher(entry):
                    full_path = os.path.join(d, entry)
                    if os.path.isfile(full_path):
                        result.append(full_path)
        except OSError:
            # Skip directories we cannot access
            continue

    return sorted(result)

