@classmethod
def ansible_config_manager(cls):
    """Gets the ansible config manager. """
    try:
        return cls._ansible_config_manager
    except AttributeError:
        from ansible.config.manager import ConfigManager
        from ansible.errors import AnsibleError
        import os
        # Determine config file path
        cfg_path = os.getenv("ANSIBLE_CONFIG")
        if cfg_path and not os.path.isabs(cfg_path):
            cfg_path = os.path.abspath(cfg_path)
        if not cfg_path:
            # Path fallback order: user, system
            fallback_paths = [
                os.path.join(os.path.expanduser("~"), ".ansible.cfg"),
                "/etc/ansible/ansible.cfg",
            ]
            for path in fallback_paths:
                if os.path.exists(path):
                    cfg_path = path
                    break
            else:
                cfg_path = None
        manager = ConfigManager()
        if cfg_path:
            try:
                manager.load_from_file(cfg_path)
            except Exception as exc:
                raise AnsibleError(f"Failed to load ansible config from {cfg_path!r}: {exc}") from exc
        cls._ansible_config_manager = manager
        return manager

