def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []

    # Helper to fetch a value from args, which may be a dict or an object
    def _get_arg_value(name):
        if hasattr(args, "get"):  # dict-like
            return args.get(name, None)
        return getattr(args, name, None)

    for opt in options_spec:
        # Determine the option's name; try common keys
        opt_name = opt.get("arg") or opt.get("name") or opt.get("dest")
        if not opt_name:
            continue

        # Only process options that have a conditional requirement
        if "required_when" not in opt:
            continue

        cond = opt["required_when"]
        matched = False

        # Condition can be a dictionary: all key/value pairs must match
        if isinstance(cond, dict):
            matched = all(_get_arg_value(k) == v for k, v in cond.items())

        # Condition can be an iterable of names: any true value satisfies it
        elif isinstance(cond, (list, tuple)):
            matched = any(_get_arg_value(c) for c in cond)

        # Condition can be a single string: argument must exist and be truthy
        elif isinstance(cond, str):
            matched = bool(_get_arg_value(cond))

        # Fallback: treat truthy condition as satisfied
        else:
            matched = bool(cond)

        if matched:
            required.append(opt_name)

    return required

