    # Determine the underlying Python type
    base_type_name = spec_option.get('type', 'str')
    base_type = {
        'int': int,
        'float': float,
        'str': str,
        'bool': lambda v: v.lower() in ('true', '1', 'yes', 'on'),
        'list': lambda v: v.split(',') if isinstance(v, str) else list(v),
