        if isinstance(value, str) and sep and not isinstance(base_type, list):
            parts = value.split(sep)
        else:
            parts = [value]

        try:
            converted = [base_type(part) for part in parts]
        except Exception as e:
            raise ValueError(f"Error converting '{value}' to {base_type_name}: {e}") from e

        # Validate choices if specified
        if choices:
