def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into.
    :param extra_vars: Iterable of extra variables. May be a dict, a list of
                       dicts, a list of ``key=value`` strings, or a single
                       ``key=value`` string.

    Returns:
        dict: The updated dictionary.
    """
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

    if not extra_vars:
        return vars_dict

    # Helper to merge a mapping into the target
    def _merge_mapping(m):
        if not isinstance(m, dict):
            raise TypeError(f"Expected dict to merge, got {type(m).__name__}")
        for k, v in m.items():
            vars_dict[k] = v

    # Single dict pass-through
    if isinstance(extra_vars, dict):
        _merge_mapping(extra_vars)
    # Iterable of dicts or strings
    elif isinstance(extra_vars, (list, tuple)):
        for item in extra_vars:
            if isinstance(item, dict):
                _merge_mapping(item)
            elif isinstance(item, str):
                # Attempt to parse key=value
                if "=" in item:
                    key, val = item.split("=", 1)
                    key = key.strip()
                    val = val.strip()
                    if key:
                        vars_dict[key] = val
            else:
                raise TypeError(f"Unsupported type in extra_vars: {type(item).__name__}")
    # Single string "key=value"
    elif isinstance(extra_vars, str):
        if "=" in extra_vars:
            key, val = extra_vars.split("=", 1)
            key = key.strip()
            val = val.strip()
            if key:
                vars_dict[key] = val
        else:
            raise ValueError(f"String extra_var '{extra_vars}' is not in key=value format")
    else:
        raise TypeError(f"Unsupported type for extra_vars: {type(extra_vars).__name__}")

    return vars_dict

