def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        # Try to import yaml if available
        import yaml
    except Exception:
        yaml = None

    # Ensure we have a valid path
    if not plugin_dir or not os.path.isdir(plugin_dir):
        raise ValueError(f"'{plugin_dir}' is not a valid directory")

    # Determine the spec file name (common patterns)
    spec_filenames = ["plugin.yaml", "spec.yaml", "plugin.yml", "spec.yml",
                      "plugin.json", "spec.json"]
    spec_file = None
    for fname in spec_filenames:
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_file = candidate
            break

    if spec_file is None:
        raise FileNotFoundError("No plugin spec file found in directory")

    # Load the spec file
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith((".yaml", ".yml")):
                if yaml is None:
                    raise RuntimeError("yaml module is required to parse YAML files")
                data = yaml.safe_load(f)
            else:
                data = json.load(f)
    except Exception as exc:
        raise RuntimeError(f"Failed to load plugin spec: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("Spec file must contain a top-level dictionary")

    # Flatten nested dictionary
    flat_dict = {}

    def _flatten(prefix, obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_prefix = f"{prefix}.{k}" if prefix else k
                _flatten(new_prefix, v)
        else:
            flat_dict[prefix] = obj

    _flatten("", data)
    return flat_dict

